(() => {
  const M = window.BreatheModel
  const KEY = { config:'breathe-web-config', session:'breathe-web-session', stats:'breathe-web-stats', history:'breathe-web-history' }
  const $ = id => document.getElementById(id)
  const store = { get(k, fallback) { try { return localStorage.getItem(k) || fallback } catch (_) { return fallback } }, set(k,v) { try { localStorage.setItem(k,v) } catch (_) {} }, clear() { try { Object.values(KEY).forEach(k => localStorage.removeItem(k)) } catch (_) {} } }
  let config = M.parseConfig(store.get(KEY.config,'')), stats = M.parseStats(store.get(KEY.stats,'')), history = M.parseHistory(store.get(KEY.history,'')), session = M.parseSession(store.get(KEY.session,''))
  let selectedId = config.defaultTechniqueId || 'box', raf = 0, editor = null, audio = null, lastPhase = ''
  const now = () => Date.now(), technique = () => M.techniqueById(selectedId, config) || M.techniqueById('box', config)
  const save = () => { store.set(KEY.config, JSON.stringify(config)); store.set(KEY.session, JSON.stringify(session)); store.set(KEY.stats, JSON.stringify(stats)); store.set(KEY.history, JSON.stringify(history)) }
  const toast = text => { $('toast').textContent = text; $('toast').classList.add('show'); setTimeout(() => $('toast').classList.remove('show'), 2600) }
  const tone = t => `tone-${t || 'neutral'}`
  function selected(t) { selectedId = t.id; config.defaultTechniqueId = t.id; save(); renderCatalogue(); renderSession() }
  function effective() { return M.effectiveElapsedMs(session, now()) }
  function beginAudio() { if (config.silent) return; try { audio ||= new (window.AudioContext || window.webkitAudioContext)(); if (audio.state === 'suspended') audio.resume() } catch (_) {} }
  function cue(kind, label) { if (config.silent) return; if (config.cueVoice && window.speechSynthesis) { try { speechSynthesis.cancel(); const u = new SpeechSynthesisUtterance(label); u.rate=.82; u.volume=.55; speechSynthesis.speak(u); return } catch (_) {} } try { if (!audio) return; const o=audio.createOscillator(), g=audio.createGain(); o.frequency.value=kind==='end'?660:420; g.gain.setValueAtTime(.0001,audio.currentTime); g.gain.exponentialRampToValueAtTime(.08,audio.currentTime+.02); g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+.24); o.connect(g).connect(audio.destination); o.start(); o.stop(audio.currentTime+.26) } catch (_) {} }
  function credit(pass, completed) { const t=technique(), cycleMs=M.cycleSeconds(t)*1000, elapsed=Math.min(effective(), cycleMs*Math.max(1,session.cycles)), cycles=Math.min(session.cycles, Math.floor(elapsed/cycleMs)); if (cycles <= 0) return false; const seconds=Math.max(0, Math.floor((elapsed-session.skipMs)/1000)), started=session.startedAtMs||now(), date=M.dateStringOf(started); stats.totals.sessions += 1; stats.totals.seconds += seconds; stats.totals.cycles += cycles; stats.daily[date] ||= {sessions:0,seconds:0,cycles:0}; stats.daily[date].sessions += 1; stats.daily[date].seconds += seconds; stats.daily[date].cycles += cycles; const previous=stats.lastActiveDate; if (previous !== date) { const yesterday=M.dateStringOf(started-86400000); stats.streak = previous===yesterday ? stats.streak+1 : 1; stats.lastActiveDate=date; stats.bestStreak=Math.max(stats.bestStreak,stats.streak) } history.sessions.unshift({techniqueId:t.id,startedAtMs:started,seconds,cycles,completed:!!completed}); history.sessions=history.sessions.slice(0,M.SESSION_HISTORY_MAX); return true }
  function resetSession() { session=M.defaultSession(); save(); renderAll() }
  function notifyCompletion() { if (!config.notifyOnEnd || !('Notification' in window) || Notification.permission !== 'granted') return; try { new Notification('Breathe session complete', { body: `${technique().name} · ${session.cycles} cycles` }) } catch (_) {} }
  function openGuide() { if (!$('guide').open) { $('guide').showModal(); $('guide').focus(); if (document.fullscreenEnabled && document.documentElement.requestFullscreen) document.documentElement.requestFullscreen().catch(() => {}) } }
  function closeGuide() { if ($('guide').open) $('guide').close(); if (document.fullscreenElement && document.exitFullscreen) document.exitFullscreen().catch(() => {}) }
  function finish(completed=false, loopRoll=false) { if (session.state==='IDLE') return; const did=credit(true,completed); if (loopRoll && session.loop && completed) { session.state='RUNNING'; session.startedAtMs=now(); session.savedAtMs=now(); session.elapsedMs=0; session.skipMs=0; save(); cue('phase','Breathe'); renderAll(); return } session.state='IDLE'; session.savedAtMs=now(); save(); if (did && completed) { cue('end','Breathe'); notifyCompletion() } renderAll() }
  function reconcile() { if (session.state!=='RUNNING') return; const t=technique(), total=M.sessionSeconds(t,session.cycles)*1000; if (effective()>=total) finish(true,true) }
  function start() { beginAudio(); const t=technique(); if (t.warning && !confirm(`${t.name}: ${t.warning}\n\nContinue?`)) return; const count=Math.max(1,Number(config.defaultCycles)||t.defaultCycles||1); session={...M.defaultSession(),state:'RUNNING',techniqueId:t.id,cycles:count,sessionId:`web-${now()}`,startedAtMs:now(),savedAtMs:now(),silent:config.silent,loop:config.loop}; selectedId=t.id; save(); cue('phase','In'); renderAll(); if (config.overlayOnStart) openGuide(); loop() }
  function toggle() { beginAudio(); if (session.state==='IDLE') return start(); const t=now(); if (session.state==='RUNNING') { session.elapsedMs=effective(); session.savedAtMs=t; session.state='PAUSED' } else { session.savedAtMs=t; session.state='RUNNING' } save(); renderAll(); if(session.state==='RUNNING') loop() }
  function skip() { if(session.state!=='RUNNING') return; const r=M.resolve(session,technique(),now()); if(!r.isHold) return; const jump=Math.max(0,r.phaseRemainingMs); session.elapsedMs=effective()+jump; session.savedAtMs=now(); session.skipMs+=jump; save(); renderSession() }
  function toggleLoop() { if(session.state==='IDLE') config.loop=!config.loop; else session.loop=!session.loop; save(); renderAll(); toast((session.loop||config.loop)?'Loop enabled':'Loop disabled') }
  function loop() { cancelAnimationFrame(raf); if(session.state!=='RUNNING') return; raf=requestAnimationFrame(() => { reconcile(); renderSession(); if(session.state==='RUNNING') loop() }) }
  function renderSession() { const t=technique(), r=M.resolve(session,t,now()), active=session.state!=='IDLE', remaining=M.breathRemainingMs(t,r); $('session-status').textContent=session.state==='RUNNING'?'BREATHING':session.state==='PAUSED'?'PAUSED':r.done?'COMPLETE':'READY'; $('phase-label').textContent=active?r.phaseLabel:(r.done?'Complete':'Choose a technique'); $('phase-detail').textContent=active?`${t.name} · ${M.formatClock(r.isHold?r.phaseElapsedMs:remaining)} seconds`:'Your sessions stay on this device.'; $('orb-time').textContent=active?M.formatClock(r.isHold?r.phaseElapsedMs:remaining):'—'; $('orb').style.transform=`scale(${active?r.orbScale:.32})`; $('orb').style.boxShadow=config.reduceMotion?'none':`0 0 80px ${r.isHold?'#FFCC0055':'#66CCFF55'}`; $('session-progress').style.width=`${Math.round(r.sessionFraction*100)}%`; $('cycle-progress').textContent=active?`cycle ${Math.min(r.cycleIndex+1,r.cycleCount)}/${r.cycleCount}`:'Ready'; $('session-time').textContent=active?M.formatClock(r.sessionElapsedMs):'0:00'; $('pause-btn').textContent=session.state==='PAUSED'?'Resume':'Pause'; $('pause-btn').disabled=!active; $('skip-btn').disabled=!(session.state==='RUNNING'&&r.isHold); $('finish-btn').disabled=!active; $('start-btn').textContent=active?'Restart':'Start'; $('warning').classList.toggle('hidden',!(t.warning&&active&&r.cycleIndex===0)); $('warning').textContent=t.warning||''; if($('guide').open) renderGuide(r,t); if(active&&lastPhase&&lastPhase!==r.phaseIndex) cue('phase',cueWord(r.phaseKind)); lastPhase=active?r.phaseIndex:'' }
  function cueWord(k) { return k===M.PHASE.INHALE||k===M.PHASE.INHALE_TOP?'In':k===M.PHASE.EXHALE?'Out':k===M.PHASE.SWITCH?'Switch':k===M.PHASE.POWER_BREATHS?'Breathe':'Hold' }
  function renderCatalogue() { const all=M.allTechniques(config), used={}; history.sessions.forEach(s=>used[s.techniqueId]=(used[s.techniqueId]||0)+1); const groups=[['Most used',all.filter(t=>used[t.id]).sort((a,b)=>(used[b.id]||0)-(used[a.id]||0)).slice(0,3)],['Core',all.filter(t=>t.family==='core')],['Energising',all.filter(t=>t.family==='energising')],['Clinical',all.filter(t=>t.family==='clinical')],['Yours',all.filter(t=>t.family==='custom')]]; $('catalogue-list').innerHTML=groups.filter(g=>g[1].length).map(([name,list])=>`<div class="technique-group"><h3>${name}</h3>${list.map(t=>`<article class="technique ${tone(t.tone)} ${t.id===selectedId?'selected':''}" data-id="${t.id}"><div class="technique-top"><span class="technique-name">${esc(t.name)}</span><span class="badge">${esc(t.pattern)} · ${t.defaultCycles} cycles</span></div><p>${esc(t.blurb||'Custom breathing pattern.')}</p>${t.warning?`<p class="warning">${esc(t.warning)}</p>`:''}</article>`).join('')}</div>`).join(''); document.querySelectorAll('.technique').forEach(e=>e.onclick=()=>selected(M.techniqueById(e.dataset.id,config))) }
  function renderMetrics() { const t=M.totals(stats), streak=M.streakOf(stats), days=M.dailyBuckets(stats,7,now()), breakdown=M.techniqueBreakdown(history,30,now(),config), heat=M.hourHeatmap(history,30,now()), rate=M.completionRate(history,30,now()), suggestion=M.suggestTechnique(history,stats,now(),config); if(!t.sessions){$('metrics-content').innerHTML='<p>No completed cycles yet. Start small and your local history will appear here.</p>';return} const max=Math.max(1,...days.map(d=>d.seconds)); $('metrics-content').innerHTML=`<div class="cards"><div class="metric"><strong>${Math.round(days.at(-1).seconds/60)}m</strong><span>Today</span></div><div class="metric"><strong>${Math.round(days.reduce((a,d)=>a+d.seconds,0)/60)}m</strong><span>Last 7 days</span></div><div class="metric"><strong>${streak.current}</strong><span>Day streak · best ${streak.best}</span></div><div class="metric"><strong>${Math.round(rate.pct*100)}%</strong><span>30-day completion</span></div></div><h3>Seven days</h3><div class="bars">${days.map(d=>`<div class="bar"><i style="height:${Math.max(3,d.seconds/max*100)}%" title="${Math.round(d.seconds/60)} minutes"></i><small>${d.date.slice(5)}</small></div>`).join('')}</div><h3>Thirty-day techniques</h3><div class="breakdown">${breakdown.map(x=>`<div class="break-row"><span>${esc(x.name)}</span><i style="width:${Math.max(3,x.pct*100)}%"></i><small>${Math.round(x.seconds/60)}m</small></div>`).join('')||'<p>No sessions.</p>'}</div><h3>Practice by hour</h3><div class="heatmap">${heat.map((n,i)=>`<i style="opacity:${Math.min(.95,.12+n*.15)}" title="${i}:00 · ${n} sessions"></i>`).join('')}</div><p>Lifetime: ${t.sessions} sessions · ${Math.round(t.seconds/60)} minutes · ${t.cycles} cycles.</p>${suggestion?`<div class="notice"><strong>Suggestion:</strong> ${esc(suggestion.reason)} <button data-try="${suggestion.techniqueId}">Try</button></div>`:''}`; const tryBtn=document.querySelector('[data-try]'); if(tryBtn)tryBtn.onclick=()=>{selectedId=tryBtn.dataset.try;renderCatalogue();location.hash='practice'} }
  function renderSettings() { const items=[['silent','Silent cues','Suppress chimes and spoken cues',config.silent],['cueVoice','Spoken cues','Speak phase words when available',config.cueVoice],['notifyOnEnd','Completion notification','Notify after permission is granted',config.notifyOnEnd],['overlayOnStart','Guide on start','Open the guide when a session starts',config.overlayOnStart],['reduceMotion','Reduce motion','Disable glow and ring motion',config.reduceMotion],['nudge.enabled','Remind me','Reminder while this page is open only',config.nudge.enabled]]; $('settings-form').innerHTML=items.map(([key,label,help,value])=>`<div class="setting"><div><label>${label}</label><small>${help}</small></div><input type="checkbox" data-setting="${key}" ${value?'checked':''}></div>`).join('')+`<div class="setting"><div><label>Default cycles</label><small>Used when starting a session</small></div><input type="number" min="1" max="100" data-setting="defaultCycles" value="${config.defaultCycles}"></div><div class="setting"><div><label>Reminder interval</label><small>Open-page interval in minutes</small></div><input type="number" min="5" max="1440" data-setting="nudge.everyMinutes" value="${config.nudge.everyMinutes}"></div><div class="setting"><div><label>Browser permission</label><small>Notification permission is requested only here.</small></div><button id="notify-permission">Allow notifications</button></div>`; document.querySelectorAll('[data-setting]').forEach(e=>e.onchange=()=>{const key=e.dataset.setting, value=e.type==='checkbox'?e.checked:Number(e.value); if(key.startsWith('nudge.'))config.nudge[key.slice(6)]=value;else config[key]=value;save();renderSession()}); $('notify-permission').onclick=async()=>{if(!('Notification'in window)){toast('Notifications are unavailable; reminders stay in-page');return} const p=await Notification.requestPermission();toast(p==='granted'?'Notifications enabled':'Permission not granted; reminders stay in-page')}; }
  let reminderShownAt=0
  function reminderTick(){ if(!config.nudge.enabled || session.state!=='IDLE') return; const latest=history.sessions[0]?.startedAtMs||0; const interval=Math.max(5,Number(config.nudge.everyMinutes)||90)*60000; if(now()-latest<interval || now()-reminderShownAt<interval) return; reminderShownAt=now(); if('Notification' in window && Notification.permission==='granted') new Notification('Time to breathe',{body:'A short session is waiting for you.'}); else toast('Reminder: take a breathing break while this page is open.') }
  setInterval(reminderTick, 60000)
  function renderAll(){renderCatalogue();renderSession();renderMetrics();renderSettings()}
  function renderGuide(r,t){$('guide-technique').textContent=t.name;$('guide-phase').textContent=r.phaseLabel;$('guide-time').textContent=M.formatClock(r.isHold?r.phaseElapsedMs:M.breathRemainingMs(t,r));$('guide-orb').style.transform=`scale(${r.orbScale})`;$('guide-pause').textContent=session.state==='PAUSED'?'Resume':'Pause';$('guide-skip').disabled=!(session.state==='RUNNING'&&r.isHold);$('guide-loop').textContent=session.loop?'Loop on':'Loop off'}
  function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  $('start-btn').onclick=()=>session.state==='IDLE'?start():(resetSession(),start()); $('pause-btn').onclick=toggle; $('skip-btn').onclick=skip; $('finish-btn').onclick=()=>finish(false,false); $('new-technique').onclick=()=>editorView(); $('close-editor').onclick=()=>$('editor').classList.add('hidden'); $('reset-data').onclick=()=>{if(confirm('Clear all Breathe sessions, custom techniques, settings, and metrics from this browser?')){store.clear();location.reload()}}; $('guide-btn').onclick=()=>openGuide(); $('guide-close').onclick=closeGuide; $('guide-pause').onclick=toggle; $('guide-skip').onclick=skip; $('guide-loop').onclick=toggleLoop; $('guide').addEventListener('click',e=>{if(e.target===$('guide'))closeGuide()}); document.addEventListener('keydown',e=>{if(!$('guide').open)return;if(e.key==='Escape'){e.preventDefault();closeGuide();return}if(e.key===' '){e.preventDefault();toggle()}else if(e.key==='ArrowRight'){e.preventDefault();skip()}else if(e.key.toLowerCase()==='l'){e.preventDefault();toggleLoop()}});
  selectedId=session.techniqueId||config.defaultTechniqueId||'box'; reconcile(); renderAll(); if(session.state==='RUNNING')loop();
})()
